from rest_framework import generics, permissions
from rest_framework.exceptions import PermissionDenied
from .models import TherapySessionTranscript
from .serializers import TherapyTranscriptSerializer

class IsSessionParticipant(permissions.BasePermission):
    def has_object_permission(self, request, view, obj):
        # Require that the user is either the attending therapist or the patient for all operations
        is_therapist = obj.attending_therapist == request.user
        is_patient = obj.patient.user == request.user
        return is_therapist or is_patient

class TherapySessionDetailView(generics.RetrieveUpdateDestroyAPIView):
    serializer_class = TherapyTranscriptSerializer
    permission_classes = [permissions.IsAuthenticated, IsSessionParticipant]
    lookup_field = "session_id"

    def get_queryset(self):
        user = self.request.user
        return TherapySessionTranscript.objects.filter(
            attending_therapist=user
        ) | TherapySessionTranscript.objects.filter(patient__user=user)
